/* Web Dashers: Geometry Dash web port loader shell (jsDelivr, pinned revision with
   CDN fallbacks). Embedded as inline HTML so it launches as a local blob - the
   shell then pulls the game from the CDN at runtime. */
var WEB_DASHERS_HTML = "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n    <meta name=\"theme-color\" content=\"#071f57\">\n    <title>Geometry Dash (MORE LEVELS)</title>\n    <link rel=\"preconnect\" href=\"https://cdn.jsdelivr.net\" crossorigin>\n    <link rel=\"dns-prefetch\" href=\"//cdn.jsdelivr.net\">\n    <style>\n      * { box-sizing: border-box; }\n      html, body { width: 100%; height: 100%; margin: 0; overflow: hidden; background: #071f57; color: #fff; font: 600 14px/1.4 Arial, sans-serif; }\n      body { display: grid; place-items: center; }\n      .loader { display: grid; justify-items: center; gap: 18px; text-align: center; }\n      .loader[hidden] { display: none; }\n      .meter { width: min(430px, 70vw); height: 14px; overflow: hidden; background: #061640; border: 3px solid #f7cf24; border-radius: 999px; box-shadow: 0 0 0 2px #111; }\n      .meter::after { display: block; width: 42%; height: 100%; content: \"\"; background: #6de3ff; animation: loading 1s ease-in-out infinite alternate; }\n      h1 { margin: 0; font-size: clamp(28px, 5vw, 56px); }\n      p { margin: 0; color: rgba(255,255,255,.78); }\n      button { min-height: 40px; padding: 0 18px; color: #07112d; background: #fff; border: 0; border-radius: 6px; font: inherit; cursor: pointer; }\n      @keyframes loading { from { transform: translateX(-15%); } to { transform: translateX(145%); } }\n      @media (prefers-reduced-motion: reduce) { .meter::after { animation: none; width: 70%; } }\n    </style>\n  </head>\n  <body>\n    <main class=\"loader\" id=\"loader\" aria-live=\"polite\">\n      <h1>Web Dashers</h1>\n      <div class=\"meter\" aria-hidden=\"true\"></div>\n      <p id=\"status\">Loading Geometry Dash...</p>\n      <button id=\"retry\" type=\"button\" hidden>Retry</button>\n    </main>\n    <script>\n      (function () {\n        \"use strict\";\n\n        var revision = \"9f086b9cd3297b9ab9625cf49ccb602a547ecae6\";\n        var repository = \"web-dashers/web-dashers.github.io\";\n        var roots = [\n          \"https://cdn.jsdelivr.net/gh/\" + repository + \"@\" + revision + \"/\",\n          \"https://fastly.jsdelivr.net/gh/\" + repository + \"@\" + revision + \"/\",\n          \"https://gcore.jsdelivr.net/gh/\" + repository + \"@\" + revision + \"/\"\n        ];\n        var status = document.getElementById(\"status\");\n        var retry = document.getElementById(\"retry\");\n        var runnerNetworkUrl = document.querySelector('meta[name=\"neo-runner\"]')\n          ? new URL(\"../neo-os/neo-runner-network.js?v=20260831-chromebook-network-v1\", document.baseURI).href\n          : \"\";\n\n        function fetchEntry(root) {\n          var controller = new AbortController();\n          var timer = window.setTimeout(function () { controller.abort(); }, 7000);\n          return fetch(root + \"index.html\", {\n            cache: \"force-cache\",\n            credentials: \"omit\",\n            signal: controller.signal\n          }).then(function (response) {\n            if (!response.ok) throw new Error(\"HTTP \" + response.status);\n            return response.text();\n          }).then(function (html) {\n            if (html.length < 500 || !/<(?:html|script|canvas)\\b/i.test(html)) {\n              throw new Error(\"Invalid game response\");\n            }\n            return { html: html, root: root };\n          }).finally(function () {\n            window.clearTimeout(timer);\n          });\n        }\n\n        function install(result) {\n          var base = '<base href=\"' + result.root.replace(/&/g, \"&amp;\").replace(/\"/g, \"&quot;\") + '\">';\n          var network = runnerNetworkUrl\n            ? '<script src=\"' + runnerNetworkUrl.replace(/&/g, \"&amp;\").replace(/\"/g, \"&quot;\") + '\"><\\/script>'\n            : \"\";\n          var html = /<head\\b[^>]*>/i.test(result.html)\n            ? result.html.replace(/<head\\b[^>]*>/i, function (head) { return head + base + network; })\n            : base + network + result.html;\n          document.open();\n          document.write(html);\n          document.close();\n        }\n\n        function load(index) {\n          index = index || 0;\n          retry.hidden = true;\n          status.textContent = \"Loading Geometry Dash...\";\n          if (index >= roots.length) {\n            status.textContent = \"Geometry Dash could not load. Check your connection and try again.\";\n            retry.hidden = false;\n            return;\n          }\n          fetchEntry(roots[index]).then(install).catch(function () { load(index + 1); });\n        }\n\n        retry.addEventListener(\"click\", function () { load(0); });\n        load(0);\n      })();\n    </script>\n  </body>\n</html>";

